pub fn decode(bytes: &str) -> Result<Msg, String> {
    let input = bytes.trim();
    match input {
        "ping" | "v1:ping" => Ok(Msg::Ping),
        _ if input.starts_with("v:2:hello:") => Ok(Msg::Hello(input[10..].to_owned())),
        _ => Err("unknown".into()),
    }
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("v:2:hello:{}", value),
    }
}

pub fn encode_versioned(msg: &Msg) -> String {
    match msg {
        Msg::Ping => format!("{}:{}", CURRENT_VERSION, encode(msg)),
        Msg::Hello(value) => format!("v:2:hello:{}", value),
    }
}

